import{_ as t,h as r,i as a,c as n,v as o,p as i,x as d,m as l,e as m,S as s}from"./chunks/framework.Dvtg8yj2.js";const N=JSON.parse('{"title":"JSON schema 约束解码","description":"","frontmatter":{"title":"JSON schema 约束解码","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/json-constrained-decode.md","filePath":"llm/json-constrained-decode.md","lastUpdated":1788454257000}'),h={name:"llm/json-constrained-decode.md"};function p(S,e,u,E,A,O){const c=r("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="json-schema-约束解码" tabindex="-1">JSON schema 约束解码 <a class="header-anchor" href="#json-schema-约束解码" aria-label="Permalink to &quot;JSON schema 约束解码&quot;">​</a></h1><div class="epigraph"><p>把合法续写写成自动机上的转移，再对词表建索引：每一步掩码可以是查表，而不必扫描整个词表去跑一遍 schema。</p><footer>—— Willard 与 Louf 的 Outlines 把 JSON Schema 降到引导生成；后续引擎把同一钩子接到服务热路径</footer></div><p>工具调用、智能体状态机、评测判分器，都希望模型吐出能 <code>json.loads</code> 的对象，而不是「看起来像 JSON 的 Markdown」。提示里写 <code>请只输出 JSON</code> 能把失败率压低一截，却压不掉漏逗号、多尾逗号、键名幻觉、数字被切成非法子词。JSON Schema 约束解码把 Schema 编进采样掩码：类型、必填键、<code>enum</code>、嵌套对象与数组在逐步生成时就被强制。它是 <a href="/llm/grammar-decode">文法约束</a> 的一个高价值特化，也是 OpenAI Structured Outputs、Outlines、XGrammar、各引擎 JSON mode 的共同产品形态。本篇只谈 Schema 这一层：哪些关键词能进自动机，哪些必须留给生成后的校验，以及流式半截 JSON 为什么不能当业务对象用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>JSON 的表面文法是 CFG：对象、数组、值可以递归嵌套。Schema 在这份文法之上又加了 <strong>结构与取值约束</strong>：<code>type</code>、<code>properties</code>、<code>required</code>、<code>additionalProperties</code>、<code>enum</code>、<code>const</code>、<code>items</code>、<code>minItems</code>、<code>$ref</code>。无约束模型既会写非法 JSON，也会写合法但不符合 Schema 的 JSON——多一个未声明键、少一个必填键、把字符串写成数字。下游用 Pydantic 校验失败后重试，成本随嵌套与枚举变大而上升，且重试分布并不等于「Schema 上的条件分布」。</p><p>另一类失败发生在 token 边界。<code>&quot;temperature&quot;</code> 可能被切成多片；<code>true</code> / <code>false</code> / <code>null</code> 与数字的科学计数法各有多种切分；字符串里的转义 <code>\\&quot;</code>、<code>\\uXXXX</code> 会让「当前是否仍在字符串内」成为必须跟踪的状态。只在字符正则上说「现在该出现键名」不够，必须相对于分词器定义消费规则。这与 Outlines 对词表索引的设定相同，只是字母表上的合法延续由 Schema 决定，而不是由用户手写的一条正则决定。</p><h3 id="schema-松紧同时改变合法集合与模型自由度" tabindex="-1">Schema 松紧同时改变合法集合与模型自由度 <a class="header-anchor" href="#schema-松紧同时改变合法集合与模型自由度" aria-label="Permalink to &quot;Schema 松紧同时改变合法集合与模型自由度&quot;">​</a></h3><p><code>additionalProperties: true</code> 且不固定键序时，合法集合很大，掩码松，模型更常把键写乱或编造字段。把键序钉死、关掉额外属性、给每个字段 <code>enum</code> 或 <code>const</code>，合法集合变小，解析变稳，也更容易把模型逼进低概率合法 token，出现重复引号或最短骨架。产品上的「要不要约束键序」不是审美问题，而是语言大小、编译成本与采样质量的联合旋钮。</p><p><span class="marginnote">约束保证的是字节能通过 Schema 的结构检查，不保证字段值在业务上为真。<code>&quot;age&quot;: 327</code> 可以完全合法。事实要靠检索、工具返回值或生成后的语义校验器，不要把 Schema 当成知识库。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>典型管线是：应用侧用 JSON Schema 或 Pydantic 模型描述对象 → 约束引擎把 Schema 编译成 FSM 或 PDA → 每步按当前状态掩码 logits → 生成结束后仍跑一次标准 JSON 解析与 Schema 校验作为断言。Outlines 的路径是把 Schema 能表达的结构降到正则或 CFG，再利用词表索引；对纯正则可表达的扁平对象，逐步开销接近查表。更深层的嵌套、<code>$ref</code> 循环与互递归对象则走上 <a href="/llm/grammar-decode">CFG / PDA</a>。OpenAI 等托管接口的 Structured Outputs 把同一契约做成服务端保证：失败应表现为拒绝采样而非「尽力而为的 JSON 模式」。</p><p>编译时要把 JSON 的空白、键的引号、冒号与逗号写进自动机，而不是指望模型「记得加标点」。<code>enum</code> 与 <code>const</code> 变成有限字符串语言，适合预先展开到 token 路径。<code>pattern</code> 字段本质是正则，应走 <a href="/llm/regex-constrained-decode">正则约束</a> 的编译器，并单独评估状态爆炸。数字的 <code>minimum</code> / <code>maximum</code> 往往 <strong>不能</strong> 便宜地编进逐步掩码：合法数字的 token 前缀集合与数值范围的关系不是局部的。工程上常见做法是结构用约束解码，范围用生成后校验或工具侧裁剪。</p>',12)),(a(),i(s,null,{default:d(()=>[m(c,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22JSON%20Schema%20%2F%20Pydantic%22%5D%20--%3E%20C%5B%22%E7%BC%96%E8%AF%91%E4%B8%BA%20FSM%20%E6%88%96%20PDA%22%5D%0A%20%20C%20--%3E%20ST%5B%22%E7%8A%B6%E6%80%81%EF%BC%9A%E5%AF%B9%E8%B1%A1%E9%94%AE%20%2F%20%E5%AD%97%E7%AC%A6%E4%B8%B2%20%2F%20%E6%95%B0%E7%BB%84%20%2F%20%E7%A9%BA%E7%99%BD%22%5D%0A%20%20ST%20--%3E%20M%5B%22%E5%90%88%E6%B3%95%20token%20%E6%8E%A9%E7%A0%81%22%5D%0A%20%20LM%5B%22%E6%A8%A1%E5%9E%8B%20logits%22%5D%20--%3E%20MASK%5B%22%E9%9D%9E%E6%B3%95%E4%BD%8D%E7%BD%AE%20-inf%22%5D%0A%20%20M%20--%3E%20MASK%0A%20%20MASK%20--%3E%20TOK%5B%22%E9%87%87%E6%A0%B7%E4%B8%8B%E4%B8%80%E4%B8%AA%20token%22%5D%0A%20%20TOK%20--%3E%20ST%0A%20%20TOK%20--%3E%20DONE%5B%22%E9%97%AD%E5%90%88%E5%90%8E%20json.loads%20%2B%20Schema%20%E6%A0%A1%E9%AA%8C%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="必填键、键序与-oneof" tabindex="-1">必填键、键序与 <code>oneOf</code> <a class="header-anchor" href="#必填键、键序与-oneof" aria-label="Permalink to &quot;必填键、键序与 `oneOf`&quot;">​</a></h3><p><code>required</code> 要求在对象结束前某几个键都出现过。自动机因此不能只记得「现在在对象里」，还要记得已出现键的集合。键集合是 \\(2^k\\) 的，键一多，状态膨胀。固定键序把问题降成一条链表：按约定顺序写完必填键再写可选键，状态数与键数线性相关。这是许多 JSON mode 默认钉死键序的原因。<code>oneOf</code> / <code>anyOf</code> 是若干分支文法的并；实现可以并行维护多个活前缀，或先让模型选判别字段再进入对应分支。判别字段若本身可被幻觉，分支会走错，Schema 仍可能满足——满足的是选中的那一支，不是业务意图。</p><h3 id="流式与半截对象" tabindex="-1">流式与半截对象 <a class="header-anchor" href="#流式与半截对象" aria-label="Permalink to &quot;流式与半截对象&quot;">​</a></h3><p>客户端若在生成中途把缓冲区当 JSON 解析，会稳定地失败：缺闭合括号、字符串未结束、最后一个数字 token 还不完整。要对齐自动机状态来展示草稿（已知键可渲染，未闭合值标为 pending），或等接受态再投递。连续批服务里，每条请求的 Schema 可能不同，编译产物要缓存；同一 Schema 的不同序列仍处于不同状态，掩码不能广播成一份。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>设当前前缀的字节为 \\(w\\)，自动机状态为 \\(s(w)\\)。下一步分布是</p> \\[p_{\\text{const}}(v \\mid w) \\propto p_\\theta(v \\mid w) \\cdot \\mathbf{1}[v \\in \\mathcal{M}(s(w))]. \\]<p>若编译完备且 token 消费与分词器一致，生成结束时 \\(w\\) 属于 Schema 对应的语言。这是结构层的定理，不是内容层的定理。<code>enum</code> 把某字段的支撑收到有限集合，模型不能「近义改写」键值——这对工具名、状态机枚举是优点，对自由文本字段则应用 <code>type: string</code> 而不是假装枚举能覆盖自然语言。</p><p><span class="marginnote">「JSON mode」若只禁止 Markdown 围栏、并不按 Schema 逐步掩码，只能降低非法率，不能保证必填键与类型。评测要分开报：可解析率、Schema 通过率、字段级准确率。三者下降点不同，混成一个「结构化成功率」会掩盖键幻觉。</span></p><h3 id="可表示性空洞在-json-上的具体样子" tabindex="-1">可表示性空洞在 JSON 上的具体样子 <a class="header-anchor" href="#可表示性空洞在-json-上的具体样子" aria-label="Permalink to &quot;可表示性空洞在 JSON 上的具体样子&quot;">​</a></h3><p>数字 <code>0.1</code>、整数 <code>1000</code>、unicode 转义、空对象 <code>{}</code>、空数组 <code>[]</code> 都是高频空洞来源：分词器可能没有单 token 的 <code>:</code> 与 <code>&quot;key&quot;</code> 的理想拼接，或把 <code>.0</code> 切成模型在当前状态下不能走的片。结果是 Schema 允许、逐步掩码却走投无路，或被迫绕远路写出怪异空白。评测集应包含嵌套数组、空容器、unicode 键、大整数与布尔，而不是只测扁平的三个字符串字段。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用逐步约束替代生成后的 Schema 校验。编译器与运行时都可能有 token 跨越 bug；校验器是廉价的断言。也不要把跨字段不变量（时间区间、校验和、外键存在）硬塞进 JSON Schema 的结构关键词——那会把自动机变成业务规则引擎，状态爆炸且仍然不完备。这类规则放在工具返回值或二次校验，失败则让模型在 <strong>已合法的骨架</strong> 上改字段，而不是整段重写。</p><p>托管 JSON mode、开源引擎、llama.cpp GBNF 生成的 JSON 文法，三者对 <code>additionalProperties</code>、<code>$ref</code>、<code>patternProperties</code> 的覆盖不同。移植时以官方 Schema 子集文档为准，不要假设 Draft 2020-12 的所有关键词都能进掩码。Willard &amp; Louf（arXiv:2307.09702）给出索引式引导的复杂度论点；XGrammar（arXiv:2411.15100）给出 CFG 服务热路径的实现对照。具体某版的微秒数不要写进架构定义。</p><p><span class="marginnote">把所有 logit 关掉只留一个 token，等于按 Schema 最短路径打印模板，模型分数被忽略。调试字段内容变差时，先看 <code>enum</code> 是否过小、键序是否把高概率键排到后面，再看温度。过紧 Schema 会把多样本变成同一骨架。</span></p><h3 id="与工具调用的交接" tabindex="-1">与工具调用的交接 <a class="header-anchor" href="#与工具调用的交接" aria-label="Permalink to &quot;与工具调用的交接&quot;">​</a></h3><p>函数调用常被实现成「外层固定 JSON 对象，<code>arguments</code> 字段再套一层 Schema」。外层键名稳定，前缀缓存友好；内层参数才是约束的重点。参数里若嵌入自由文本（用户原话、检索片段），不要对那段文本再套正则或枚举，否则会把用户输入截断成「像参数的合法串」。约束的边界应停在结构，把不信任的字符串当不透明 payload，交给应用侧消毒——这与 <a href="/llm/prompt-injection">提示注入</a> 的输出处理是同一条防线的不同层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>JSON Schema 约束解码把类型、必填键与枚举编进逐步掩码，目标是可解析且符合 Schema，不是事实正确。</li><li>键序、<code>additionalProperties</code> 与 <code>required</code> 的状态集合直接决定编译规模和模型自由度。</li><li>数值范围、跨字段不变量通常留给生成后校验；<code>pattern</code> 走正则编译器并防状态爆炸。</li><li>流式半截 JSON 不可当业务对象；掩码必须按序列，Schema 编译产物可跨请求缓存。</li><li>评测拆开可解析率、Schema 通过率、字段准确率；注意数字与转义上的可表示性空洞。</li><li>出处：Willard &amp; Louf, <em>Efficient Guided Generation for Large Language Models</em>, arXiv:2307.09702（Outlines）；Dong et al., XGrammar, arXiv:2411.15100。引擎 JSON mode 以各厂商文档为准。</li></ul>',19))])}const B=t(h,[["render",p]]);export{N as __pageData,B as default};
